//
//  EigenvectorByComponentParityTests.swift
//  BusinessMath
//
//  The contract with ClassGraph (ADR-010): what this library stores for `eigenvector-centrality-by-component`
//  must be what ClassGraph's own copy of the code stored, so ClassGraph can delete its copy and keep reading
//  its records. ByComponentParityGoldens.swift holds, for each synthetic case in ByComponentParityCases, the
//  encoded MetricEnvelope (JSONEncoder .sortedKeys) that ClassGraph's ComponentwiseEigenvector.swift (main
//  d38b363) produced, generated by a scratch program outside both repositories. If a test here fails, a stored
//  record has changed meaning: fix the code, never the constant.
//
//  A case with `exact == false` has decimal weights, for which WeightedGraph's dictionary-order total makes
//  the last bit of a score differ between processes; it is compared on structure exactly and on values to a
//  tolerance. Every other case is compared byte for byte.
//

import Foundation
import Testing
import TestSupport
@testable import BusinessMath

private func encoded<Value: Encodable>(_ value: Value) throws -> String {
	let encoder = JSONEncoder()
	encoder.outputFormatting = [.sortedKeys]
	return String(decoding: try encoder.encode(value), as: UTF8.self)
}

private func decoded<Value: Decodable>(_ type: Value.Type, _ text: String) throws -> Value {
	try JSONDecoder().decode(type, from: Data(text.utf8))
}

private func compute(_ item: ByComponentParityCase) throws -> ComponentwiseScores<String> {
	let built = try WeightedGraph(edges: item.edges, isolatedNodes: item.isolated)
	return try ComponentwiseEigenvectorMetric<String>(maxIterations: item.maxIterations, tolerance: item.tolerance)
		.compute(on: built)
}

private func golden(_ name: String) throws -> String {
	try #require(ByComponentGoldens.envelopes[name], "no golden for \(name)")
}

/// The stored payload of a golden envelope, read as the typed value.
private func storedResult(_ name: String) throws -> ComponentwiseScores<String> {
	let envelope = try decoded(MetricEnvelope.self, try golden(name))
	return try #require(try envelope.value(as: ComponentwiseScores<String>.self))
}

private func sameValues(_ left: [String: Double], _ right: [String: Double], tolerance: Double) -> Bool {
	guard Set(left.keys) == Set(right.keys) else { return false }
	for (node, value) in left {
		guard let other = right[node], approximatelyEqual(value, other, tolerance: tolerance) else { return false }
	}
	return true
}

private func sameBits(_ left: [String: Double], _ right: [String: Double]) -> Bool {
	guard Set(left.keys) == Set(right.keys) else { return false }
	for (node, value) in left {
		guard let other = right[node], identical(value, other) else { return false }
	}
	return true
}

@Suite("Eigenvector by component: the stored contract with ClassGraph")
struct EigenvectorByComponentParityTests {

	static let exactNames: [String] = ByComponentParityCases.all.filter(\.exact).map(\.name)
	static let decimalNames: [String] = ByComponentParityCases.all.filter { !$0.exact }.map(\.name)

	@Test("the identifier, version, title and wording are ClassGraph's, character for character")
	func descriptorText() {
		let descriptor = ComponentwiseEigenvectorMetric<String>.descriptor
		#expect(descriptor.identifier == ByComponentGoldens.identifier)
		#expect(descriptor.version == ByComponentGoldens.version)
		#expect(descriptor.title == ByComponentGoldens.title)
		#expect(descriptor.interpretation == ByComponentGoldens.interpretation)
		#expect(descriptor.highMeans == ByComponentGoldens.highMeans)
		#expect(descriptor.lowMeans == ByComponentGoldens.lowMeans)
	}

	@Test("every case has a golden, and every golden a case")
	func coverage() {
		let cases = Set(ByComponentParityCases.all.map(\.name))
		#expect(cases == Set(ByComponentGoldens.envelopes.keys))
		#expect(cases.count == ByComponentParityCases.all.count)
		#expect(ByComponentParityCases.all.count >= 20)
	}

	@Test("the envelope this library writes is byte for byte what ClassGraph wrote", arguments: exactNames)
	func envelopeBytes(name: String) throws {
		let item = try #require(ByComponentParityCases.all.first { $0.name == name })
		let envelope = try MetricEnvelope(try compute(item))
		#expect(try encoded(envelope) == (try golden(name)), "\(name)")
	}

	@Test("a decimal-weight case matches in structure exactly and in values to 1e-9", arguments: decimalNames)
	func envelopeStructure(name: String) throws {
		let item = try #require(ByComponentParityCases.all.first { $0.name == name })
		let fresh = try compute(item)
		let stored = try storedResult(name)
		#expect(sameValues(fresh.scores.scores, stored.scores.scores, tolerance: 1e-9), "\(name)")
		#expect(fresh.isolatedCount == stored.isolatedCount)
		#expect(fresh.convergence.converged == stored.convergence.converged)
		#expect(fresh.convergence.maxIterations == stored.convergence.maxIterations)
		#expect(fresh.components.map(\.anchor) == stored.components.map(\.anchor))
		#expect(fresh.components.map(\.size) == stored.components.map(\.size))
		#expect(fresh.components.map(\.convergence.converged) == stored.components.map(\.convergence.converged))
	}

	@Test("every score matches ClassGraph's bit for bit, read back from the stored text", arguments: exactNames)
	func scoreBits(name: String) throws {
		let item = try #require(ByComponentParityCases.all.first { $0.name == name })
		let fresh = try compute(item)
		let stored = try storedResult(name)
		#expect(sameBits(fresh.scores.scores, stored.scores.scores), "\(name)")
		#expect(identical(fresh.convergence.residual, stored.convergence.residual), "\(name)")
		let freshScales: [Double] = fresh.components.map(\.scale)
		let storedScales: [Double] = stored.components.map(\.scale)
		#expect(identical(freshScales, storedScales), "\(name)")
	}

	@Test("a record ClassGraph stored decodes here and re-encodes to the same bytes", arguments: exactNames + decimalNames)
	func storedDecodesAndReencodes(name: String) throws {
		let text = try golden(name)
		let envelope = try decoded(MetricEnvelope.self, text)
		#expect(try encoded(envelope) == text, "\(name)")
		let typed = try #require(try envelope.value(as: ComponentwiseScores<String>.self))
		#expect(try encoded(MetricEnvelope(typed)) == text, "\(name)")
		#expect(envelope.kind == "scores")
	}

	@Test("a stored record reads as plain scores and as diagnosed scores, and its convergence is the aggregate",
		  arguments: exactNames + decimalNames)
	func storedReadsAsScores(name: String) throws {
		let envelope = try decoded(MetricEnvelope.self, try golden(name))
		let plain = try #require(try envelope.value(as: NodeScores<String>.self))
		let typed = try storedResult(name)
		#expect(plain == typed.scores)
		let diagnosed = try #require(try envelope.value(as: DiagnosedScores<String>.self))
		#expect(diagnosed.convergence == typed.convergence)
		#expect(envelope.convergence == typed.convergence)
	}

	@Test("the stored payload has exactly the four keys, and each component exactly four")
	func storedKeys() throws {
		let text = try golden("path-star")
		let envelope = try decoded(MetricEnvelope.self, text)
		guard case .object(let fields) = envelope.payload else {
			Issue.record("the payload is not an object")
			return
		}
		#expect(Set(fields.keys) == ["scores", "convergence", "components", "isolatedCount"])
		guard case .array(let components)? = fields["components"], case .object(let first)? = components.first else {
			Issue.record("components is not an array of objects")
			return
		}
		#expect(Set(first.keys) == ["anchor", "size", "convergence", "scale"])
		#expect(components.count == 2)
	}

	@Test("the shapes the brief names: isolates 0 with their count, largest score 1, one component identical to v5")
	func conventionsInTheStoredData() throws {
		let isolates = try storedResult("karate-star-pair-isolates")
		#expect(isolates.isolatedCount == 3)
		for name in ["lone1", "lone2", "lone3"] {
			let value = try #require(isolates.scores[name])
			#expect(identical(value, 0), "\(name)")
		}
		for name in Self.exactNames {
			let stored = try storedResult(name)
			guard let peak = stored.scores.scores.values.max(), stored.components.isEmpty == false else { continue }
			#expect(identical(peak, 1), "\(name)")
		}
		let karate = try storedResult("karate")
		let built = try WeightedGraph(
			edges: try #require(ByComponentParityCases.all.first { $0.name == "karate" }).edges)
		let direct = try Centrality.eigenvectorConvergence(built)
		#expect(sameBits(karate.scores.scores, direct.scores.scores))
		#expect(karate.convergence.iterations == direct.iterations)
	}
}
